'use strict';
const $=selector=>document.querySelector(selector),math=globalThis.LabelCode;
const format=value=>new Intl.NumberFormat('en-US').format(value);
let queue=[],page=0,query='',searchRequest=0,busy=false,previewValid=false,searchValid=false,searchTotal=0;
function node(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;}
function status(text){$('#label-status').textContent=text;}
function settings(){return {...math.dimensions($('#label-width').value,$('#label-height').value),kind:$('#label-kind').value==='shelf'?'shelf':'barcode',paper:$('#label-paper').value==='roll'?'roll':'a4',barcode:$('#label-kind').value!=='shelf'||$('#label-with-barcode').checked};}
function controls(){for(const e of document.querySelectorAll('.labels-layout input, .labels-layout select, .labels-layout button'))e.disabled=busy;$('#label-previous').disabled=busy||!searchValid||page===0;$('#label-next').disabled=busy||!searchValid||(page+1)*50>=searchTotal;$('#label-print').disabled=busy||!queue.length||!previewValid;$('#label-refresh').disabled=busy||!queue.length;$('#label-clear').disabled=busy||!queue.length;$('#label-with-barcode').disabled=busy||$('#label-kind').value!=='shelf';}
function barcode(value,width){const code=math.encode(value,width,globalThis.JsBarcode),svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 '+code.modules+' 50');svg.setAttribute('preserveAspectRatio','none');svg.setAttribute('role','img');svg.setAttribute('aria-label','بارکۆد: '+value);const white=document.createElementNS('http://www.w3.org/2000/svg','rect');white.setAttribute('width',String(code.modules));white.setAttribute('height','50');white.setAttribute('fill','white');svg.append(white);for(let i=0;i<code.bits.length;){if(code.bits[i]==='0'){i++;continue;}let end=i+1;while(code.bits[end]==='1')end++;const bar=document.createElementNS('http://www.w3.org/2000/svg','rect');for(const [key,v] of Object.entries({x:i+code.quiet,y:0,width:end-i,height:50,fill:'black'}))bar.setAttribute(key,String(v));svg.append(bar);i=end;}return svg;}
function label(item,config){const e=node('div',undefined,'product-label '+config.kind);e.style.setProperty('--label-width',config.width+'mm');e.style.setProperty('--label-height',config.height+'mm');const name=node('div',item.name,'label-name');name.title=item.name;e.append(name,node('div',format(item.sale_price)+' IQD','label-price'));if(config.barcode){e.append(barcode(item.barcode,config.width-6),node('div',item.barcode,'label-value'));}return e;}
function preview(){previewValid=false;$('#label-preview').replaceChildren();$('#label-print-area').replaceChildren();try{const config=settings(),total=math.total(queue);if(config.kind==='shelf'&&config.barcode&&config.height<35)throw Error('لیبڵی نرخ لەگەڵ بارکۆد پێویستی بە بەرزی ٣٥ ملیمەتر یان زیاترە.');$('#label-total').textContent=format(total)+' لیبڵ · '+queue.length+' کاڵا';const area=$('#label-print-area');area.className=config.paper;area.style.setProperty('--label-width',config.width+'mm');area.style.setProperty('--label-height',config.height+'mm');$('#label-page-style').textContent=config.paper==='roll'?'@page{size:'+config.width+'mm '+config.height+'mm;margin:0}':'@page{size:A4 portrait;margin:8mm}';for(const item of queue){const sample=label(item,config);$('#label-preview').append(sample);for(let n=0;n<item.copies;n++)area.append(label(item,config));}if(!queue.length)$('#label-preview').append(node('p','کاڵا هەڵبژێرە بۆ پێشبینینی لیبڵ.'));previewValid=true;}catch(error){$('#label-preview').replaceChildren();$('#label-print-area').replaceChildren();status((globalThis.KashierLocale?.message(error.message)??error.message));}controls();}
function render(){const box=$('#label-queue');box.replaceChildren();for(const item of queue){const row=node('div',undefined,'label-queue-item'),field=node('label','ژمارەی لیبڵ'),input=node('input');input.type='number';input.min='1';input.max='100';input.step='1';input.value=String(item.copies);input.setAttribute('aria-label','ژمارەی لیبڵی '+item.name);input.addEventListener('change',()=>{if(busy)return;try{const value=math.copies(input.value);math.total(queue.map(x=>x.id===item.id?{...x,copies:value}:x));item.copies=value;status('');preview();}catch(error){input.value=String(item.copies);status((globalThis.KashierLocale?.message(error.message)??error.message));}});field.append(input);const remove=node('button','لابردن');remove.addEventListener('click',()=>{if(busy)return;queue=queue.filter(x=>x.id!==item.id);status('');render();});row.append(node('strong',item.name),field,remove);box.append(row);}preview();}
function add(product){if(busy)return;try{if(queue.some(x=>x.id===product.id)){status('ئەم کاڵایە لە لیستدایە؛ ژمارەی لیبڵەکانی بگۆڕە.');return;}if(queue.length>=50)throw Error('لە هەر لیستێکدا تەنها ٥٠ کاڵا هەڵبژێرە.');const config=settings();if(config.barcode)math.encode(product.barcode,config.width-6,globalThis.JsBarcode);queue.push({...product,copies:1});status('');render();}catch(error){status((globalThis.KashierLocale?.message(error.message)??error.message));}}
async function search(){if(!KashierData.loggedIn()){location.replace('auth.html?next='+encodeURIComponent('labels.html?kind='+($('#label-kind').value==='shelf'?'shelf':'barcode')));return;}const request=++searchRequest;searchValid=false;controls();$('#label-results').replaceChildren();$('#label-search-status').textContent='گەڕان لە کاڵاکان…';$('#label-previous').disabled=true;$('#label-next').disabled=true;try{const {rows,total}=await KashierData.listProducts(query,page);if(request!==searchRequest)return;searchValid=true;searchTotal=total;for(const product of rows){const row=node('div',undefined,'label-result'),info=node('div'),button=node('button','هەڵبژاردن');info.append(node('strong',product.name),node('small',format(product.sale_price)+' دینار · '+(product.barcode||'بەبێ بارکۆد')));button.addEventListener('click',()=>add(product));row.append(info,button);$('#label-results').append(row);}$('#label-search-status').textContent=rows.length?'':'هیچ کاڵایەک نەدۆزرایەوە.';$('#label-page').textContent='کۆ: '+total+' · پەڕە: '+(page+1);$('#label-previous').disabled=busy||page===0;$('#label-next').disabled=busy||(page+1)*50>=total;controls();}catch(error){if(request===searchRequest){searchValid=false;$('#label-search-status').textContent=(globalThis.KashierLocale?.message(error.message)??error.message);controls();}}}
async function refresh(print){if(busy||!queue.length)return;busy=true;controls();status('نوێکردنەوەی نرخ و بارکۆدەکان…');try{const products=await KashierData.getLabelProducts(queue.map(x=>x.id)),map=new Map(products.map(x=>[x.id,x]));if(queue.some(x=>!map.has(x.id)))throw Error('کاڵایەک نەدۆزرایەوە؛ لیستی چاپ بپشکنە و ئەو کاڵایە لاببە.');queue=queue.map(x=>({...map.get(x.id),copies:x.copies}));status('نرخ و بارکۆدەکان لە داتابەیسەوە نوێ کرانەوە.');render();if(print&&previewValid)requestAnimationFrame(()=>window.print());}catch(error){previewValid=false;$('#label-print-area').replaceChildren();status((globalThis.KashierLocale?.message(error.message)??error.message));}finally{busy=false;controls();}}
$('#label-search-form').addEventListener('submit',event=>{event.preventDefault();if(busy)return;query=$('#label-query').value;page=0;search();});$('#label-query').addEventListener('input',()=>{searchRequest++;searchValid=false;$('#label-results').replaceChildren();$('#label-page').textContent='';$('#label-search-status').textContent='بۆ گەڕان دوگمەی گەڕان دابگرە.';controls();});$('#label-previous').addEventListener('click',()=>{if(!busy&&searchValid&&page>0){page--;search();}});$('#label-next').addEventListener('click',()=>{if(!busy&&searchValid&&(page+1)*50<searchTotal){page++;search();}});
for(const key of ['label-kind','label-paper','label-width','label-height','label-with-barcode'])$('#'+key).addEventListener('change',()=>{if(!busy){status('');preview();}});
$('#label-refresh').addEventListener('click',()=>refresh(false));$('#label-print').addEventListener('click',()=>refresh(true));$('#label-clear').addEventListener('click',()=>{if(!busy){queue=[];status('');render();}});
if(new URLSearchParams(location.search).get('kind')==='shelf'){$('#label-kind').value='shelf';$('#label-width').value='70';$('#label-height').value='40';}
render();search();
